__NUXT_JSONP__("/inclusion/eventos/presentan_unidas_alianza_para_la_defensa_de_los_derechos_laborales_de_las_mujeres_trabajadoras", (function(a,b,c,d,e,f){return {data:[{post:{slug:"presentan_unidas_alianza_para_la_defensa_de_los_derechos_laborales_de_las_mujeres_trabajadoras",title:"Presentan UNIDAS, alianza para la defensa de los derechos laborales de las mujeres trabajadoras ",date:"2025-03-25T23:36:26.298Z",img:"https:\u002F\u002Fucarecdn.com\u002Ff7975a04-d37b-443e-b748-60caefa261b1\u002F","img-alt":"UNIDAS",autor:"Ethos",category:"inclusion",extracto:"En 2024, solo el 46% de las mujeres en edad de trabajar participaron en el mercado de trabajo. El 55.6% de ellas lo hace en condiciones de informalidad. Por cada 100 pesos que gana un hombre, una mujer percibe solo 85. ",toc:[],body:{type:"root",children:[{type:b,tag:d,props:{},children:[{type:a,value:"En el marco del mes de la Mujer Trabajadora, cuatro organizaciones de la sociedad civil presentan la alianza UNIDAS, una red nacional de mujeres trabajadoras de sectores precarizados que busca promover y garantizar sus derechos laborales en México. "}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"La iniciativa impulsada por Fundación Avina, ProDESC, Oxfam México y Ethos Innovación en Políticas Públicas, agrupa las demandas de trabajadoras del hogar, de la maquila textil, de plataformas digitales y del sector agrícola. "}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"UNIDAS surge como respuesta a la falta de acceso a derechos laborales y la alta informalidad en estos sectores. “En México, más de la mitad de la población trabaja en la economía informal, lo que implica desprotección social y falta de acceso a derechos, especialmente para las mujeres en situación de mayor vulnerabilidad. Entre las causas de esta problemática se encuentran la ausencia de políticas laborales y servicios públicos adecuados, las desigualdades estructurales y la sobrecarga de cuidados, señaló Patricia Carmona, gerente programática de Fundación Avina. "}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Las cifras muestran la profundidad de la desigualdad. En 2024, solo el 45.9% de las mujeres en edad de trabajar participaron en el mercado laboral, mientras que entre los hombres la cifra fue mucho mayor: 8 de cada 10 están ocupados. Además, el 55.6% de las mujeres ocupadas lo hace en condiciones de informalidad, mientras que en los hombres la cifra es del 53.6%. La brecha salarial también persiste: por cada 100 pesos que gana un hombre en el sector formal, una mujer percibe solo 85, y, en el sector informal, la disparidad es aún mayor, de acuerdo con el Instituto Mexicano para la Competitividad. "}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Las condiciones laborales en los sectores prioritarios de UNIDAS son alarmantes: "}]},{type:a,value:c},{type:b,tag:"ul",props:{},children:[{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Sector agrícola: El 90% de las personas trabajadoras en el campo no cuenta con contrato formal (Instituto Nacional de Desarrollo Social, 2020; ENOE, 2024), y el 86.6% carece de seguridad social (CONEVAL, 2024). "}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Trabajo del hogar: El 96% carece de un contrato escrito y el 71.3% no recibe prestaciones laborales (ENOE, 2024). "}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Industria de la indumentaria: El 52% del personal trabaja sin seguridad social (Acción Ciudadana Frente a la Pobreza, 2022).  "}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Plataformas digitales: Actualmente, ninguna trabajadora de plataformas cuenta con un contrato que le reconozca como trabajadora con acceso a seguridad social y prestaciones. Sin embargo, la reciente reforma en este sector beneficiará a alrededor de 100 mil trabajadoras. "}]},{type:a,value:c}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"La reforma y las propuestas impulsadas por el gobierno de la presidenta Claudia Sheinbaum, como la regulación del trabajo en plataformas digitales, la atención a las jornaleras agrícolas y la creación de un Sistema Nacional de Cuidados, reflejan un reconocimiento oficial de la necesidad de fortalecer los derechos laborales en diversos sectores. "}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"No obstante, es fundamental ampliar estos esfuerzos para atender la precarización en sectores donde las mujeres representan la mayoría de la fuerza laboral y que enfrentan altos niveles de vulnerabilidad y desprotección social y laboral. “La desigualdad salarial y el menor acceso a empleos con prestaciones y protección social impactarán negativamente en las condiciones de jubilación y pensiones de las mujeres”, advirtió Mónica Corona, directora de Inclusión y Desarrollo Sostenible de Ethos Innovación en Políticas Públicas. "}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"El trabajo colectivo y la organización política son herramientas fundamentales para visibilizar y transformar estas injusticias. \"La diversidad de las experiencias de las mujeres trabajadoras es nuestra mayor fortaleza. UNIDAS es parte de la respuesta a esta realidad que los colectivos de mujeres organizadas políticamente que han visibilizado las injusticias y problemáticas que enfrentan y buscan cambiar las relaciones de poder que normalizan la precariedad en la vida y el trabajo”, aseguró Valeria Berumen, oficial de Comunicación Estratégica de ProDESC. "}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"\"La injusticia laboral que enfrentan las mujeres en México no es un fenómeno aislado, sino una consecuencia directa de un sistema que perpetúa la desigualdad. Con UNIDAS, buscamos transformar las condiciones estructurales que las mantienen en la precariedad y generar cambios reales para que el trabajo digno y con derechos sea una realidad para todas\", afirmó Alexandra Haas, directora de Oxfam México. "}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Las colectivas de base integrantes de UNIDAS recalcaron que su voz no es aislada, sino colectiva y con fuerza política. “Desde UNIDAS, nos posicionamos como sujetas de cambio, exigiendo nuestro derecho a condiciones laborales dignas y a una vida libre de violencia y explotación”, mencionó Ana Medina, integrante de Lady Drivers. La creación de UNIDAS es un acto de resistencia, organización y lucha colectiva. "}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"En el evento participaron representantes de las Secretarías de las Mujeres y del Trabajo y Previsión Social, quienes saludaron la iniciativa y compartieron el trabajo que se está realizando desde el gobierno en la búsqueda de garantizar condiciones laborales dignas en el país. "}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"UNIDAS trabajará con mujeres trabajadoras y autoridades para visibilizar estas barreras estructurales y promover soluciones que garanticen condiciones laborales dignas y equitativas. A través de la organización colectiva y la incidencia en políticas públicas, la alianza busca transformar las condiciones laborales y cerrar las brechas de desigualdad en el país."}]}]},dir:"\u002Feventos",path:"\u002Feventos\u002Fpresentan_unidas_alianza_para_la_defensa_de_los_derechos_laborales_de_las_mujeres_trabajadoras",extension:".md",createdAt:f,updatedAt:f}}],fetch:{},mutations:[]}}("text","element","\n","p","li","2025-04-23T06:21:15.374Z")));